import{_ as n,o as i,c as t,a1 as e}from"./chunks/framework.DxqwKiYY.js";const s="/pelatihan-webgis-big/assets/image1.xPC-hjkx.png",g="/pelatihan-webgis-big/assets/image2.DL2yg5v8.png",r="/pelatihan-webgis-big/assets/image3.BjtNMgCl.png",p="/pelatihan-webgis-big/assets/image.Djyp8050.png",o="/pelatihan-webgis-big/assets/image5.-BggbSwi.png",m="/pelatihan-webgis-big/assets/image6.DIOtS4H3.png",l="/pelatihan-webgis-big/assets/image%201.CrnRTi56.png",u="/pelatihan-webgis-big/assets/image8.BpbrAjtf.png",k="/pelatihan-webgis-big/assets/image%202.w1173GPj.png",d="/pelatihan-webgis-big/assets/image10.rver_4DR.png",b="/pelatihan-webgis-big/assets/image11.CMpu3tMW.png",h="/pelatihan-webgis-big/assets/image12.Bb8ghAC4.png",c="/pelatihan-webgis-big/assets/image13.CbsQXx_-.png",_="/pelatihan-webgis-big/assets/image14.BJ-GLjVj.png",w="/pelatihan-webgis-big/assets/image15.Vattsri3.png",f="/pelatihan-webgis-big/assets/image16.DBAiQbuA.png",y="/pelatihan-webgis-big/assets/image17.C6eCJeX5.png",v="/pelatihan-webgis-big/assets/image18.D2q1IBIh.png",K="/pelatihan-webgis-big/assets/image19.DUKq-zQt.png",P="/pelatihan-webgis-big/assets/image20.BBWZRTHf.png",j="/pelatihan-webgis-big/assets/image%203.CIphsUE-.png",C="/pelatihan-webgis-big/assets/image22.DyFpF7Ga.png",T="/pelatihan-webgis-big/assets/image23.B4G5HUas.png",D="/pelatihan-webgis-big/assets/image24.Dx9k2lWD.png",S="/pelatihan-webgis-big/assets/image%204.BQmY2A0e.png",B="/pelatihan-webgis-big/assets/image26.v1iyCreP.png",N="/pelatihan-webgis-big/assets/image27.D2tDdgeS.png",x="/pelatihan-webgis-big/assets/image28.Dpu7T--k.png",V="/pelatihan-webgis-big/assets/image29.CoHxRTVQ.png",I="/pelatihan-webgis-big/assets/image%205.HL5RbHWm.png",W="/pelatihan-webgis-big/assets/image%206.D7XFKCBP.png",A="/pelatihan-webgis-big/assets/image32.Cn5SuP6K.png",F="/pelatihan-webgis-big/assets/image%207.DpWCzwhy.png",G="/pelatihan-webgis-big/assets/image%208.CWjgqRz7.png",J=JSON.parse('{"title":"Kontrol Kamera dan Navigasi: Penggunaaan flyto, setView, heading, pitch dan rol","description":"","frontmatter":{},"headers":[],"relativePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Kontrol Kamera dan Navigasi Penggunaaan flyto, set.md","filePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Kontrol Kamera dan Navigasi Penggunaaan flyto, set.md"}'),q={name:"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Kontrol Kamera dan Navigasi Penggunaaan flyto, set.md"};function H(M,a,L,R,Q,$){return i(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="kontrol-kamera-dan-navigasi-penggunaaan-flyto-setview-heading-pitch-dan-rol" tabindex="-1">Kontrol Kamera dan Navigasi: Penggunaaan flyto, setView, heading, pitch dan rol <a class="header-anchor" href="#kontrol-kamera-dan-navigasi-penggunaaan-flyto-setview-heading-pitch-dan-rol" aria-label="Permalink to &quot;Kontrol Kamera dan Navigasi: Penggunaaan flyto, setView, heading, pitch dan rol&quot;">​</a></h1><h2 id="pembuatan-fungsi-kontrol-dan-navigasi-kamera" tabindex="-1"><strong>Pembuatan Fungsi Kontrol dan Navigasi Kamera</strong> <a class="header-anchor" href="#pembuatan-fungsi-kontrol-dan-navigasi-kamera" aria-label="Permalink to &quot;**Pembuatan Fungsi Kontrol dan Navigasi Kamera**&quot;">​</a></h2><ol><li><p>Tahap pertama buat file baru pada folder <strong>components</strong> dengan nama <strong>addCameraNav.jsx</strong>.</p><p><img src="'+s+'" alt=""></p></li><li><p>Selanjutnya pada tahap kedua buat struktur dasar modul <strong>addCameraNav()</strong> yang berfungsi sebagai wadah untuk seluruh fitur navigasi kamera, dengan parameter <strong>viewer</strong> sebagai instance Cesium Viewer dan <strong>opsi</strong> sebagai konfigurasi tambahan, serta mengambil library Cesium dari <strong>window.Cesium</strong> agar dapat digunakan.</p><p><img src="'+g+'" alt=""></p></li><li><p>Pada tahap ketiga buat variabel dengan parameter <strong>lokasiAwal</strong> untuk menentukan posisi awal kamera dan <strong>tampilkanPanel</strong> untuk menentukan apakah tombol navigasi akan ditampilkan.</p><p><img src="'+r+'" alt=""></p></li><li><p>Tahap keempat buat fungsi <strong>lihatLangsung()</strong> yang digunakan untuk memindahkan tampilan kamera secara langsung ke lokasi tertentu berdasarkan koordinat, ketinggian, dan arah pandangan kamera.</p><p><img src="'+p+'" alt="image.png"></p></li><li><p>Selanjutnya didalam fungsi <strong>lihatLangsung,</strong> buat fungsi untuk mengatur dan memindahkan posisi tampilan kamera secara langsung ke lokasi menggunakan <strong>viewer.camera.setView</strong>.</p><p><img src="'+o+'" alt=""></p></li><li><p>Tahap berikutnya dalam fungsi <strong>viewer.camera.setView</strong> buat fungsi berupa <strong>destination</strong> untuk menentukan lokasi tujuan kamera berdasarkan nilai longitude, latitude, dan ketinggian yang kemudian diubah ke format koordinat yang digunakan oleh Cesium.</p><p><img src="'+m+'" alt=""></p></li><li><p>Selanjutnya tambahkan fungsi <strong>orientation</strong> untuk mengatur arah dan sudut pandangan kamera, yang terdiri dari <strong>heading</strong> untuk menentukan arah, <strong>pitch</strong> untuk menentukan kemiringan pandangan, dan <strong>roll</strong> untuk menentukan kemiringan posisi kamera.</p><p><img src="'+l+'" alt="image.png"></p></li><li><p>Pada tahap kelima buat fungsi <strong>terbangKe()</strong> sebagai wadah untuk mengatur perpindahan kamera menuju lokasi tertentu dengan animasi.</p><p><img src="'+u+'" alt=""></p></li><li><p>Selanjutnya pada fungsi tersebut tambahkan <strong>viewer.camera.flyTo()</strong> untuk membuat kamera bergerak atau terbang secara animasi menuju lokasi tujuan.</p><p><img src="'+k+'" alt="image.png"></p></li><li><p>Kemudian tambahkan fungsi berupa <strong>destination</strong> untuk menentukan lokasi tujuan kamera serta tambahkan <strong>orientation</strong> untuk mengatur arah dan sudut pandangan kamera, yang terdiri dari <strong>heading, pitch</strong> dan <strong>roll.</strong></p><p><img src="'+d+'" alt=""></p></li><li><p>Pada tahap keenam buat fungsi <strong>resetKeAwal()</strong> untuk mengembalikan posisi kamera ke lokasi awal yang telah ditentukan.</p><p><img src="'+b+'" alt=""></p></li><li><p>Selanjutnya didalam fungsi tersebut tambahkan kondisi <strong>if</strong> yang digunakan untuk memastikan data lokasiAwal tersedia sebelum kamera melakukan perpindahan.</p><p><img src="'+h+'" alt=""></p></li><li><p>Tahap berikutnya tambahkan fungsi <strong>terbangKe()</strong> untuk memindahkan kamera kembali menuju lokasi awal dengan animasi.</p><p><img src="'+c+'" alt=""></p></li><li><p>Didalam fungsi <strong>terbangKe()</strong> tambahkan parameter untuk mengambil nilai <strong>latitude, longitude,</strong> dan <strong>ketinggian</strong> dari data <strong>lokasiAwal</strong> sebagai tujuan kamera, serta tambahkan parameter untuk mengambil pengaturan arah dan sudut pandangan kamera dari <strong>lokasiAwal</strong>, seperti <strong>heading, pitch,</strong> dan <strong>roll.</strong></p><p><img src="'+_+'" alt=""></p></li><li><p>Tahap ketujuh buat fungsi <strong>putarKiri()</strong> yang berfungsi untuk memutar arah pandangan kamera ke sebelah kiri.</p><p><img src="'+w+'" alt=""></p></li><li><p>Selanjutnya buat variabel untuk mengambil nilai arah atau posisi putaran kamera yang sedang digunakan.</p><p><img src="'+f+'" alt=""></p></li><li><p>Kemudian tambahkan fungsi <strong>viewer.camera.setView()</strong> untuk memperbarui arah pandangan kamera.</p><p><img src="'+y+'" alt=""></p></li><li><p>Tahapan berikutnya didalam <strong>viewer.camera</strong> tambahkan parameter <strong>orientasi</strong> kamera yang akan digunakan setelah kamera diputar.</p><p><img src="'+v+'" alt=""></p></li><li><p>Selanjutnya dalam orientasi tambahkan parameter arah kamera yang dikurangi sebesar 15 derajat untuk memutar pandangan ke kiri, sementara nilai pitch dan roll tetap dipertahankan agar kemiringan dan posisi kamera tidak berubah.</p><p><img src="'+K+'" alt=""></p></li><li><p>Tahap kedelapan buat fungsi <strong>putarKanan()</strong> dengan parameter yang sama dengann putar kiri, tetapi pada parameter arah kamera dalam fungsi putarKanan ditambahkan dengan 15 untuk memutar pandangan kekanan.</p><p><img src="'+P+'" alt=""></p></li><li><p>Pada tahap kesembilan buat kondisi <strong>if</strong> untuk memeriksa apakah panel navigasi perlu ditampilkan atau tidak berdasarkan nilai <strong>tampilkanPanel</strong>.</p><p><img src="'+j+'" alt="image.png"></p></li><li><p>Kemudian tambahkan variabel untuk membuat container dengan elemen div yang akan digunakan sebagai wadah untuk seluruh tombol navigasi kamera.</p><p><img src="'+C+'" alt=""></p></li><li><p>Selanjutnya buat <strong>panel.style.cssText</strong> yang akan digunakan untuk pengaturan tampilan pada panel seperti posisi, warna, ukuran, dan tata letak agar panel terlihat di atas peta.</p><p><img src="'+T+'" alt=""></p></li><li><p>Kemudian tambahkan variabel <strong>const tombolStyle</strong> sebagai pengaturan tampilan yang akan digunakan bersama oleh seluruh tombol navigasi.</p><p><img src="'+D+'" alt=""></p></li><li><p>Tahap berikutnya buat variabel yang akan digunakan sebagai daftar tombol yang akan digunakan untuk mengontrol arah kamera.</p><p><img src="'+S+'" alt="image.png"></p></li><li><p>Selanjutnya buat fungsi berupa <strong>daftarTombol</strong> untuk membuat tombol secara otomatis.</p><p><img src="'+B+'" alt=""></p></li><li><p>Pada fungsi <strong>daftarTombol</strong> buat elemen HTML button untuk setiap tombol navigasi.</p><p><img src="'+N+'" alt=""></p></li><li><p>Selanjutnya buat teks dan style diterapkan pada tombol yang telah dibuat, kemudian tambahkan aksi saat diklik sebelum dimasukkan ke dalam panel navigasi.</p><p><img src="'+x+'" alt=""></p></li><li><p>Tahap terakhir pada fungsi <strong>if (tampilkanPanel)</strong> tambahkan ke dalam container Cesium agar dapat ditampilkan di atas peta 3D.</p><p><img src="'+V+'" alt=""></p></li><li><p>Pada tahap terakhir, seluruh fungsi navigasi kamera dikembalikan agar dapat digunakan kembali dari luar modul untuk mengatur pergerakan dan arah pandangan kamera.</p><p><img src="'+I+'" alt="image.png"></p></li></ol><h2 id="integrasi-fungsi-kontrol-dan-navigasi-kamera-dengan-cesium-viewer" tabindex="-1"><strong>Integrasi Fungsi Kontrol dan Navigasi Kamera dengan Cesium Viewer</strong> <a class="header-anchor" href="#integrasi-fungsi-kontrol-dan-navigasi-kamera-dengan-cesium-viewer" aria-label="Permalink to &quot;**Integrasi Fungsi Kontrol dan Navigasi Kamera dengan Cesium Viewer**&quot;">​</a></h2><ol><li><p>Tahap pertama, pada file <strong>CesiumViewer.jsx</strong> pada <strong>function addContent3D</strong> tambahkan variabel untuk kontrolKamera dan panggil <strong>addCameraNav</strong>.</p><p><img src="'+W+'" alt="image.png"></p></li><li><p>Tahap kedua tambahkan <strong>kontrolKamera</strong> untuk memanggil fungsi <strong>terbangKe()</strong> sehingga kamera dapat bergerak secara animasi menuju lokasi awal dengan ketinggian, arah, dan sudut pandangan yang telah ditentukan.</p><p><img src="'+A+'" alt=""></p></li><li><p>Hasil tampilan untuk kontrol kamera ketika posisi dirotasi ke arah kiri ataupun kanan.</p><p><img src="'+F+'" alt="image.png"></p></li><li><p>Hasil tampilan ketika posisi direset dan mengaktifkan fitur flyto.</p><p><img src="'+G+'" alt="image.png"></p></li></ol>',5)])])}const U=n(q,[["render",H]]);export{J as __pageData,U as default};
